        );

    bytes32 private constant _CALL_ID_PREFIX =
        keccak256("LABORCOIN_GOVERNANCE_V16_0_PROPOSAL_EXECUTION");

    bytes4 private constant _ERC20_BALANCE_OF_SELECTOR =
        0x70a08231;
